#include "JavaItemIcons.h"
#include <cassert>
#include <iostream>
#include <vector>
extern "C" TcpeJavaSession* __wrap_tcpe_java_connect(const char*,size_t,const char*,size_t,bool){return reinterpret_cast<TcpeJavaSession*>(1);}
extern "C" void __wrap_tcpe_java_close(TcpeJavaSession*){}
static void init(JavaGameSession& s){s.compass.dimension="minecraft:overworld";s.compass.defaultSpawn.valid=true;s.compass.defaultSpawn.dimension=s.compass.dimension;s.compass.defaultSpawn.position={{100,64,0}};s.compass.lastDeath=s.compass.defaultSpawn;}
static std::vector<std::string> trace(bool alternate){JavaGameSession session;init(session);JavaGameSession::Item item;item.resourceId="minecraft:compass";std::vector<std::string> out;for(unsigned t=1;t<80;++t){auto gui=JavaItemIcons::animatedResource(session,item,.5,.5,90,t,1);out.push_back(gui);if(alternate){auto held=JavaItemIcons::animatedResource(session,item,.5,.5,90,t,1);assert(gui==held);JavaItemIcons::animatedResource(session,item,.5,.5,270,t,2,false);assert(JavaItemIcons::animatedResource(session,item,.5,.5,90,t,1)==gui);JavaGameSession::Item invalid=item;invalid.hasLodestoneTracker=true;JavaItemIcons::animatedResource(session,invalid,.5,.5,90,t,1);assert(JavaItemIcons::animatedResource(session,item,.5,.5,90,t,1)==gui);session.compass.defaultSpawn.valid=false;JavaItemIcons::animatedResource(session,item,.5,.5,90,t,1);session.compass.defaultSpawn.valid=true;assert(JavaItemIcons::animatedResource(session,item,.5,.5,90,t,1)==gui);}}return out;}
int main(){assert(trace(false)==trace(true));JavaGameSession session;init(session);JavaGameSession::Item item;item.resourceId="minecraft:compass";auto first=JavaItemIcons::animatedResource(session,item,.5,.5,90,1,1);for(unsigned t=2;t<100;++t)JavaItemIcons::animatedResource(session,item,.5,.5,90,t,1);++session.chatScope;assert(JavaItemIcons::animatedResource(session,item,.5,.5,90,100,1)==first);for(unsigned t=101;t<200;++t)JavaItemIcons::animatedResource(session,item,.5,.5,90,t,1);++session.worldRevision;assert(JavaItemIcons::animatedResource(session,item,.5,.5,90,200,1)==first);for(unsigned t=201;t<300;++t)JavaItemIcons::animatedResource(session,item,.5,.5,90,t,1);session.compass.dimension="minecraft:the_nether";session.compass.defaultSpawn.dimension=session.compass.dimension;assert(JavaItemIcons::animatedResource(session,item,.5,.5,90,300,1)==first);for(unsigned t=301;t<400;++t)JavaItemIcons::animatedResource(session,item,.5,.5,90,t,1);assert(JavaItemIcons::animatedResource(session,item,.5,.5,90,1,1)==first);
 // Remote viewers use direct heading on the very first frame, never local wobble.
 assert(JavaItemIcons::animatedResource(session,item,.5,.5,0,1,2,false)=="minecraft:compass_08");assert(JavaItemIcons::animatedResource(session,item,.5,.5,90,1,3,false)=="minecraft:compass_00");assert(session.connect("fixture.invalid","fixture",false));init(session);for(unsigned t=2;t<100;++t)JavaItemIcons::animatedResource(session,item,.5,.5,90,t,1);assert(session.connect("fixture.invalid","fixture",false));init(session);assert(JavaItemIcons::animatedResource(session,item,.5,.5,90,100,1)==first);for(unsigned t=101;t<200;++t)JavaItemIcons::animatedResource(session,item,.5,.5,90,t,1);session.disconnect();init(session);assert(JavaItemIcons::animatedResource(session,item,.5,.5,90,200,1)==first);std::cout<<"Actual compass helper:79 alternating HUD/held ticks,remote/invalid-item independence,scope/world/dimension/tick rewind,actual reconnect/disconnect resets and remote direct heading PASS (CPU)"<<std::endl;}
